<?php
require_once __DIR__.'/includes/auth.php';
$defaults=[
'logo'=>'','logo_width'=>'155px','logo_height'=>'48px','header_height'=>'76px','header_background'=>'#ffffff',
'menu_color'=>'#234737','menu_hover'=>'#1f6a49','menu_active'=>'#1f6a49','menu_size'=>'12px','menu_weight'=>'700','menu_gap'=>'28px',
'header_border_color'=>'#1f5f43','header_border_width'=>'5px','button_background'=>'#28684c','button_hover'=>'#1f5a41','button_text'=>'#ffffff',
'button_radius'=>'5px','show_button'=>'1','button_text_label'=>'Book Now','button_url'=>'/booking.php','sticky'=>'1','mobile_menu'=>'1',
'mobile_breakpoint'=>'900px','mobile_background'=>'#ffffff','mobile_menu_color'=>'#234737','transparent_home'=>'0','header_shadow'=>'none'
];
$file=__DIR__.'/../header-settings.json'; $settings=$defaults;
if(is_file($file)){$x=json_decode(@file_get_contents($file),true);if(is_array($x))$settings=array_merge($settings,$x);}
$saved=false;
if($_SERVER['REQUEST_METHOD']==='POST'){
 admin_verify_csrf();
 foreach($defaults as $k=>$v){ if(in_array($k,['sticky','mobile_menu','show_button','transparent_home'],true)) continue; if(isset($_POST[$k])) $settings[$k]=trim((string)$_POST[$k]); }
 foreach(['sticky','mobile_menu','show_button','transparent_home'] as $k) $settings[$k]=isset($_POST[$k])?'1':'0';
 file_put_contents($file,json_encode($settings,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX); $saved=true;
}
function hb_color($v){return preg_match('/^#[0-9a-fA-F]{6}$/',(string)$v)?$v:'#ffffff';}
function hb_e($v){return admin_e($v);}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><title>Header Builder</title><link rel="stylesheet" href="assets/css/admin.css"><style>
.wrap{max-width:1100px;margin:24px auto;padding:0 18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:22px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.field label{display:block;font-weight:700;font-size:13px;margin-bottom:7px}.field input[type=text],.field select{width:100%;box-sizing:border-box;padding:11px;border:1px solid #d7dce1;border-radius:8px}.field input[type=color]{width:100%;height:42px;border:1px solid #d7dce1;border-radius:8px;padding:2px}.check{display:flex;align-items:center;gap:8px;font-weight:700;margin:10px 0}.save{background:#198754;color:#fff;border:0;border-radius:8px;padding:12px 20px;font-weight:800;cursor:pointer}.notice{padding:12px 15px;background:#eaf7ee;border:1px solid #b9dfc4;border-radius:9px;margin-bottom:18px}.hint{font-size:12px;color:#667085}.preview{border:1px solid #ddd;border-radius:12px;overflow:hidden;background:#f8fafc}.preview-header{height:76px;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 28px;border-bottom:5px solid #1f5f43}.preview-logo{width:110px;height:35px;background:#e5e7eb;border-radius:5px}.preview-nav{display:flex;gap:20px;align-items:center;font-size:12px;font-weight:700}.preview-btn{padding:10px 15px;background:#28684c;color:#fff;border-radius:5px}.preview-body{height:90px;display:grid;place-items:center;color:#667085;font-size:13px}@media(max-width:700px){.grid{grid-template-columns:1fr}.preview-nav{display:none}}
</style></head><body><?php $pageTitle='Header Builder'; include __DIR__.'/includes/header.php'; ?><main class="wrap"><h1>Header Builder</h1><p>Atur tampilan header website langsung dari Admin. Perubahan diterapkan pada frontend yang menggunakan <b>includes/header.php</b>.</p><?php if($saved):?><div class="notice">Header settings berhasil disimpan dan siap diterapkan di website.</div><?php endif;?>
<section class="card"><h2>Logo</h2><div class="grid"><div class="field"><label>Logo Path / URL</label><input type="text" id="logoPreview" name="logo_preview" value="<?=hb_e($settings['logo'])?>" placeholder="uploads/logo.png"><div class="hint">Kosongkan untuk menggunakan Site Logo dari Settings.</div></div><div class="field"><label>Logo Width</label><input type="text" name="logo_width" value="<?=hb_e($settings['logo_width'])?>" form="headerForm"></div><div class="field"><label>Logo Height</label><input type="text" name="logo_height" value="<?=hb_e($settings['logo_height'])?>" form="headerForm"></div></div></section>
<form method="post" id="headerForm"><input type="hidden" name="logo" id="logoHidden" value="<?=hb_e($settings['logo'])?>"><input type="hidden" name="csrf" value="<?=hb_e(admin_csrf())?>">
<section class="card"><h2>Header Layout</h2><div class="grid"><div class="field"><label>Header Height</label><input type="text" name="header_height" value="<?=hb_e($settings['header_height'])?>"></div><div class="field"><label>Header Background</label><input type="color" value="<?=hb_color($settings['header_background'])?>" oninput="this.nextElementSibling.value=this.value"><input type="text" name="header_background" value="<?=hb_e($settings['header_background'])?>"></div><div class="field"><label>Border Color</label><input type="color" value="<?=hb_color($settings['header_border_color'])?>" oninput="this.nextElementSibling.value=this.value"><input type="text" name="header_border_color" value="<?=hb_e($settings['header_border_color'])?>"></div><div class="field"><label>Border Width</label><input type="text" name="header_border_width" value="<?=hb_e($settings['header_border_width'])?>"></div><div class="field"><label>Header Shadow</label><input type="text" name="header_shadow" value="<?=hb_e($settings['header_shadow'])?>" placeholder="none / 0 4px 18px rgba(0,0,0,.10)"></div></div><label class="check"><input type="checkbox" name="sticky" <?=$settings['sticky']==='1'?'checked':''?>> Sticky Header</label><label class="check"><input type="checkbox" name="transparent_home" <?=$settings['transparent_home']==='1'?'checked':''?>> Transparent Header on Homepage</label></section>
<section class="card"><h2>Navigation Menu</h2><div class="grid"><div class="field"><label>Menu Text Color</label><input type="color" value="<?=hb_color($settings['menu_color'])?>" oninput="this.nextElementSibling.value=this.value"><input type="text" name="menu_color" value="<?=hb_e($settings['menu_color'])?>"></div><div class="field"><label>Menu Hover Color</label><input type="color" value="<?=hb_color($settings['menu_hover'])?>" oninput="this.nextElementSibling.value=this.value"><input type="text" name="menu_hover" value="<?=hb_e($settings['menu_hover'])?>"></div><div class="field"><label>Menu Active Color</label><input type="color" value="<?=hb_color($settings['menu_active'])?>" oninput="this.nextElementSibling.value=this.value"><input type="text" name="menu_active" value="<?=hb_e($settings['menu_active'])?>"></div><div class="field"><label>Menu Font Size</label><input type="text" name="menu_size" value="<?=hb_e($settings['menu_size'])?>"></div><div class="field"><label>Menu Font Weight</label><select name="menu_weight"><?php foreach(['400','500','600','700','800'] as $w):?><option value="<?=$w?>" <?=$settings['menu_weight']===$w?'selected':''?>><?=$w?></option><?php endforeach;?></select></div><div class="field"><label>Menu Gap</label><input type="text" name="menu_gap" value="<?=hb_e($settings['menu_gap'])?>"></div></div></section>
<section class="card"><h2>Book Now Button</h2><label class="check"><input type="checkbox" name="show_button" <?=$settings['show_button']==='1'?'checked':''?>> Show Book Now Button</label><div class="grid"><div class="field"><label>Button Text</label><input type="text" name="button_text_label" value="<?=hb_e($settings['button_text_label'])?>"></div><div class="field"><label>Button URL</label><input type="text" name="button_url" value="<?=hb_e($settings['button_url'])?>"></div><div class="field"><label>Background</label><input type="color" value="<?=hb_color($settings['button_background'])?>" oninput="this.nextElementSibling.value=this.value"><input type="text" name="button_background" value="<?=hb_e($settings['button_background'])?>"></div><div class="field"><label>Hover</label><input type="color" value="<?=hb_color($settings['button_hover'])?>" oninput="this.nextElementSibling.value=this.value"><input type="text" name="button_hover" value="<?=hb_e($settings['button_hover'])?>"></div><div class="field"><label>Text Color</label><input type="color" value="<?=hb_color($settings['button_text'])?>" oninput="this.nextElementSibling.value=this.value"><input type="text" name="button_text" value="<?=hb_e($settings['button_text'])?>"></div><div class="field"><label>Border Radius</label><input type="text" name="button_radius" value="<?=hb_e($settings['button_radius'])?>"></div></div></section>
<section class="card"><h2>Mobile Header</h2><label class="check"><input type="checkbox" name="mobile_menu" <?=$settings['mobile_menu']==='1'?'checked':''?>> Enable Mobile Menu</label><div class="grid"><div class="field"><label>Breakpoint</label><input type="text" name="mobile_breakpoint" value="<?=hb_e($settings['mobile_breakpoint'])?>"></div><div class="field"><label>Mobile Background</label><input type="color" value="<?=hb_color($settings['mobile_background'])?>" oninput="this.nextElementSibling.value=this.value"><input type="text" name="mobile_background" value="<?=hb_e($settings['mobile_background'])?>"></div><div class="field"><label>Mobile Menu Color</label><input type="color" value="<?=hb_color($settings['mobile_menu_color'])?>" oninput="this.nextElementSibling.value=this.value"><input type="text" name="mobile_menu_color" value="<?=hb_e($settings['mobile_menu_color'])?>"></div></div></section>
<button class="save" type="submit">Save Header Settings</button><script>document.getElementById("headerForm").addEventListener("submit",function(){document.getElementById("logoHidden").value=document.getElementById("logoPreview").value;});</script></form></main></body></html>
